+
+  useEffect(() => {
+    if (!open || !hostRef.current) return;
+
+    const terminal = new Terminal({
+      cursorBlink: true,
+      convertEol: true,
+      scrollback: 5000,
+      fontFamily: '"JetBrains Mono Variable", "JetBrains Mono", monospace',
